
/* FLORESTA V233 — espada forjada: 6 FBX originais, combo físico por clique.
   NÃO altera a árvore de ataques do machado, martelo ou lança.
   Distribuição: One Hand Sword Combo (4 golpes), Slash 4/5 + Attack 2
   (3 golpes alternativos), Slash 6 (corrida), Attack 3 (aéreo).
   Código preparado para HTML offline: @FBX_DATA@ será inserido na montagem. */
(()=>{'use strict';
  const VERSION='V234';
  const FILES={"normal":"","slash4":"","slash5":"","slash6":"","attack2":"","attack3":""};
  const ATTACK_JUMP_PACKED='';
  const SWORD_IDS=new Set(['forged_silver_sword','forged_silver_longsword']);
  const MOVES={
    normal:['combo_1','combo_2','combo_3','combo_4'],
    alt:['slash4','slash5','attack2']
  };
  const label={combo_1:'Corte de uma mão I',combo_2:'Corte de uma mão II',combo_3:'Corte de uma mão III',combo_4:'Finalização de uma mão',slash4:'Golpe com escudo I',slash5:'Golpe com escudo II',attack2:'Finalizador alternativo',slash6:'Investida com espada',attack3:'Ataque aéreo'};
  label.attackJump='Golpe de espada: ataque + pulo';
  const impactFractions={combo_1:.77,combo_2:.49,combo_3:.58,combo_4:.38,slash4:.56,slash5:.53,attack2:.60,slash6:.50,attack3:.60};
  impactFractions.attackJump=.57;
  const swingSpeeds={combo_1:1.28,combo_2:1.24,combo_3:1.22,combo_4:1.18,slash4:1.16,slash5:1.14,attack2:1.20,slash6:1.24,attack3:1.18};
  swingSpeeds.attackJump=1.18;
  const sleep=ms=>new Promise(r=>setTimeout(r,ms));
  const status=message=>{const s=document.getElementById('status');if(s)s.textContent=message;};
  let THREE=null,game=null,tfp=null,hand=null,attackAPI=null,mixer=null;
  let active=null,waiting=null,lastFinished=null,nextSwing=760000,impactCount=0,actionTick=0;
  let loaded=false,failed=null,clips={},actions={},lastTime=performance.now(),shake=0;
  const isSword=()=>SWORD_IDS.has(window.gameForgedEquipmentV230?.right)&&window.gameRightHand?.current==='axe';
  const mobile=()=>window.__CAVE_PLATFORM==='mobile'||matchMedia('(pointer:coarse)').matches;
  const inventoryBlocked=()=>!!(window.gameInventory?.isOpen||window.gameCraft?.active||window.gameForgeV230?.active||
      document.body.classList.contains('crafting-active')||document.body.classList.contains('mobile-ui-paused')||
      document.getElementById('florestaFront')?.hidden===false||window.gameRoll?.active||window.gamePlayerHit?.active||
      window.gameLumber?.carrying||window.gameZombie?.playerHp<=0);
  const valid=()=>loaded&&isSword()&&!inventoryBlocked();
  async function inflate(b64){
    const bin=atob(b64),out=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++)out[i]=bin.charCodeAt(i);
    if(!('DecompressionStream' in window))throw Error('Este navegador precisa oferecer DecompressionStream (gzip).');
    return new Response(new Blob([out]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();
  }
  function prepareClip(source,name){
    const clip=source.clone();clip.name=name;
    // A pose de corpo inteiro é real, não uma oscilação procedural do braço.
    // O motor do personagem comanda translação mundial, evitando teleporte do FBX.
    clip.tracks=clip.tracks.filter(t=>/\.quaternion$/i.test(t.name)&&!/Hand(Thumb|Index|Middle|Ring|Pinky)/i.test(t.name));
    clip.resetDuration();
    return clip;
  }
  function splitCombo(clip){
    // Limites definidos pela análise do movimento real do pulso no FBX de 4,533s:
    // picos de golpe nos segundos ~1,1 / 1,9 / 3,1 / 3,9.
    const duration=clip.duration;
    const cuts=[0,1.40,2.45,3.55,duration];
    for(let j=0;j<4;j++){
      const a=Math.round(cuts[j]*30),b=Math.round(cuts[j+1]*30);
      const name='combo_'+(j+1);
      clips[name]=THREE.AnimationUtils.subclip(clip,name,a,b,30);
      if(!clips[name].tracks.length||clips[name].duration<=.1)throw Error('Combo incompleto: '+name);
    }
  }
  async function loadFBXs(){
    // Os 6 FBX foram convertidos offline conservando TODOS os keyframes
    // quaternions do corpo (22 ossos) e os tempos originais. Carrega de modo
    // local sem fetch e sem precisar interpretar novamente o FBX ao abrir HTML.
    const spec=[['normal','One Hand Sword Combo (2).fbx'],['slash4','Sword And Shield Slash (4).fbx'],['slash5','Sword And Shield Slash (5).fbx'],['slash6','Sword And Shield Slash (6).fbx'],['attack2','Sword And Shield Attack (2).fbx'],['attack3','Sword And Shield Attack (3).fbx']];
    for(const [id,name] of spec){
      const parsed=JSON.parse(new TextDecoder().decode(await inflate(FILES[id])));
      const tracks=parsed.tracks.map(t=>new THREE.QuaternionKeyframeTrack(t.name,t.t,t.v));
      const source=new THREE.AnimationClip(name,parsed.duration,tracks);
      const clip=prepareClip(source,name);
      if(id==='normal')splitCombo(clip);
      else clips[id]=clip;
    }
    // FBX Sword And Shield Attack.fbx enviado para a combinacao ataque -> pulo.
    const jumpData=JSON.parse(new TextDecoder().decode(await inflate(ATTACK_JUMP_PACKED)));
    const jumpTracks=jumpData.tracks.map(t=>new THREE.QuaternionKeyframeTrack(t.name,t.t,t.v));
    clips.attackJump=prepareClip(new THREE.AnimationClip('Sword And Shield Attack - Ataque e Pulo',jumpData.duration,jumpTracks),'attackJump');
    const names=Object.keys(clips);
    const available=new Set();
    tfp.model.traverse(o=>{if(o.isBone)available.add(o.name)});
    const matching=clips.combo_1.tracks.filter(t=>available.has(t.name.slice(0,t.name.lastIndexOf('.'))));
    if(matching.length<12)throw Error('O avatar ativo não corresponde ao rig Mixamo ('+matching.length+' ossos compatíveis).');
    mixer=new THREE.AnimationMixer(tfp.model);
    for(const [name,clip] of Object.entries(clips)){
      const a=mixer.clipAction(clip,tfp.model);
      a.setLoop(THREE.LoopOnce,1);a.clampWhenFinished=true;
      actions[name]=a;
    }
    loaded=true;
    console.info('[ESPADA V233] 6 FBX convertidos, '+names.length+' clipes, '+matching.length+' ossos compatíveis.');
  }
  function keyDown(code){return !!game?.keys?.has?.(code)}
  function isRunning(){return (keyDown('ShiftLeft')||keyDown('ShiftRight')||document.getElementById('mobileRunBtn')?.classList.contains('active'))&&
      (keyDown('KeyW')||keyDown('KeyA')||keyDown('KeyS')||keyDown('KeyD')||Math.hypot(game?.stick?.x||0,game?.stick?.y||0)>.15);}
  function isAirborne(){return game?.physics186?.grounded===false;}
  function updateHud(){
    const hud=document.getElementById('swordComboHudV232');if(!hud)return;
    hud.hidden=!isSword()||inventoryBlocked();
    if(hud.hidden)return;
    const prefix=active?.type==='normal'?'ESPADA · COMBO':active?.type==='alt'?'ESPADA · ALTERNATIVO':'ESPADA';
    hud.textContent=active?prefix+'  '+(active.index+1)+'/'+(MOVES[active.type]?.length||1):'ESPADA  ·  clique: combo  ·  botão direito: alternativo';
  }
  function restore(){
    if(active?.action){active.action.stop();}
    mixer?.stopAllAction();
    active=null;waiting=null;
    if(attackAPI)attackAPI.active=false;
    window.__swordFullBodyPose=false;
    window.gameRightHand?.sync?.();
    updateHud();
  }
  function stopCombat(reason='end',keepFollowup=false){
    const ended=active;
    if(keepFollowup && ended?.type && MOVES[ended.type] && ended.index<MOVES[ended.type].length-1){
      lastFinished={type:ended.type,index:ended.index+1,until:performance.now()+900};
    }else lastFinished=null;
    restore();
  }
  function startClip(name,type,index){
    if(!valid())return false;
    const a=actions[name],clip=clips[name];
    if(!a||!clip)return false;
    // Ataque seguido de pulo: transicao curta, preservando o salto fisico nativo.
    const previous=(name==='attackJump')?active?.action:null;
    if(!previous){if(active?.action)active.action.stop();mixer.stopAllAction();}
    a.reset();a.enabled=true;a.setEffectiveWeight(1);a.setEffectiveTimeScale(swingSpeeds[name]||1.75);a.play();
    if(previous&&previous!==a)a.crossFadeFrom(previous,.11,false);
    const speed=swingSpeeds[name]||1.75;
    const dur=Math.max(.25,clip.duration/speed);
    active={type,index,name,action:a,duration:dur,elapsed:0,hit:false,freezeMs:0,swingId:++nextSwing};
    waiting=null;lastFinished=null;window.gameAttack.active=true;
    window.__swordFullBodyPose=true;
    status(label[name]+' • espada de ferro');updateHud();
    return true;
  }
  function request(type='normal'){
    if(!valid())return false;
    if(active){
      if(!MOVES[active.type])return false;
      if(type==='jump'||type==='run')return false;
      // O próximo golpe fica em buffer; mashing não pula animações.
      if(active.index<MOVES[active.type].length-1){waiting=active.type;return true;}
      return false;
    }
    if(type==='normal'&&isAirborne())return startClip('attack3','jump',0);
    if(type==='normal'&&isRunning())return startClip('slash6','run',0);
    const chain=MOVES[type]||MOVES.normal;
    const step=lastFinished?.type===type&&performance.now()<lastFinished.until?lastFinished.index:0;
    return startClip(chain[step],type,step);
  }
  let lastAttackJumpAt=-10000;
  function requestAttackJump(){
    // A ordem importa: primeiro ATAQUE e DEPOIS PULO, na janela inicial do golpe.
    // Nao cancela o evento de Space: o personagem continua saltando de verdade.
    if(!valid()||!active||(active.type!=='normal'&&active.type!=='alt')||
       active.elapsed>Math.min(active.duration,1.02)||
       document.body.classList.contains('v206-mounted')||
       performance.now()-lastAttackJumpAt<260)return false;
    lastAttackJumpAt=performance.now();
    return startClip('attackJump','jump',0);
  }
  function dealImpact(s){
    if(s.hit||!valid())return;
    // A marca de acerto só é aplicada após colisão confirmada.
    // Espada usa apenas colisão validada. Não dispara eventos de machado ou dano genérico.
    const ok=window.gameCombatV257?.probeSword?.(s)===true;
    if(ok){s.hit=true;impactCount++;shake=.085;}
    else{s.hit=false;}
  }
  function resync(){
    const oldPose=window.__shieldFullBodyPose;
    window.__shieldFullBodyPose=true;
    try{hand?.sync?.();}finally{window.__shieldFullBodyPose=oldPose;}
    tfp.visibleRoot.updateMatrixWorld(true);
    // Mantém a POV nos olhos, com olhar/câmera do jogo original, sem mover o mundo.
    if(tfp.eyeSocket && game.camera){
      const eye=new THREE.Vector3();tfp.eyeSocket.getWorldPosition(eye);
      game.camera.position.copy(eye);
    }
  }
  function update(dt){
    if(!loaded)return;
    if(active){
      if(!valid()){stopCombat();return;}
      const s=active;
      const freeze=Math.min(s.freezeMs||0,dt*1000);s.freezeMs=Math.max(0,(s.freezeMs||0)-freeze);
      const frame=Math.max(0,dt-freeze/1000);
      s.elapsed=Math.min(s.duration,s.elapsed+frame);
      mixer.update(frame);
      resync();
      const fraction=impactFractions[s.name]??.5;
      const phase=s.elapsed/Math.max(.001,s.duration);
      if(!s.hit&&phase>=fraction-.14&&phase<=fraction+.19)dealImpact(s);
      if(!s.hit&&phase>fraction+.19){s.hit=true;window.gameCombatV257?.miss?.();}
      if(s.elapsed>=s.duration-.035){
        if(waiting && MOVES[waiting] && s.index<MOVES[waiting].length-1){
          startClip(MOVES[waiting][s.index+1],waiting,s.index+1);
        }else stopCombat('end',true);
      }
      if(shake>0){
        const u=Math.min(1,shake/.085);
        game.camera.rotation.z+=Math.sin(s.elapsed*53)*.010*u;
        game.camera.position.y+=.008*u;
      }
    }else if(isSword() && lastFinished && performance.now()>lastFinished.until){lastFinished=null;}
    shake=Math.max(0,shake-dt);
  }
  function setupMobile(){
    if(!mobile()||document.getElementById('mobileSwordAltV232'))return;
    const style=document.createElement('style');style.id='swordComboStylesV232';
    style.textContent=`#swordComboHudV232{position:fixed;z-index:6200;right:12px;top:calc(76px + env(safe-area-inset-top,0px));pointer-events:none;color:#ffe8bd;background:rgba(16,14,17,.72);border:1px solid rgba(238,192,111,.45);border-radius:8px;padding:7px 10px;font:700 11px system-ui,sans-serif;letter-spacing:.02em;text-shadow:0 1px #000;max-width:280px}#swordComboHudV232[hidden]{display:none!important}#mobileSwordAltV232{position:fixed;z-index:7300;right:calc(18px + env(safe-area-inset-right,0px));bottom:calc(164px + env(safe-area-inset-bottom,0px));height:44px;width:92px;border-radius:15px;border:1px solid rgba(234,175,107,.8);background:rgba(45,34,38,.86);color:#ffdfad;font:800 11px system-ui,sans-serif;touch-action:none;user-select:none}#mobileSwordAltV232[hidden]{display:none!important}`;
    document.head.appendChild(style);
    const btn=document.createElement('button');btn.id='mobileSwordAltV232';btn.type='button';btn.textContent='ESPECIAL';btn.hidden=true;
    btn.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();request('alt');},{passive:false});
    document.body.appendChild(btn);
    const HUD=document.getElementById('swordComboHudV232')||document.createElement('div');HUD.id='swordComboHudV232';HUD.hidden=true;document.body.appendChild(HUD);
  }
  function setupDesktopHud(){
    const hud=document.createElement('div');hud.id='swordComboHudV232';hud.hidden=true;
    document.body.appendChild(hud);
    const style=document.createElement('style');style.textContent='#swordComboHudV232{position:fixed;z-index:6200;right:14px;top:68px;pointer-events:none;color:#ffdfb0;background:rgba(18,16,17,.72);border:1px solid #967253;border-radius:8px;padding:6px 9px;font:700 11px system-ui}#swordComboHudV232[hidden]{display:none!important}';document.head.appendChild(style);
  }
  async function init(){
    for(let i=0;i<1700;i++){
      if(window.gameReview?.trueFirstPerson?.model&&window.gameAttack?.attack&&window.gameForgedEquipmentV230&&window.gameRightHand?.sync )break;
      await sleep(30);
    }
    game=window.gameReview;tfp=game?.trueFirstPerson;hand=window.gameRightHand;attackAPI=window.gameAttack;THREE=window.__THREE_MODULE;
    if(!game||!tfp?.model||!hand?.sync||!attackAPI||!THREE)throw Error('Faltando avatar, armas ou rig original da Floresta.');
    // O botão mobile invoca window.gameAttack.attack(); só desvia com espada de ferro.
    const originalAttack=attackAPI.attack.bind(attackAPI);
    attackAPI.attack=function(...args){if(isSword())return request('normal');return originalAttack(...args)};
    // Desktop: ataque com clique -> Space. Deixa o Space seguir para o salto fisico.
    window.addEventListener('keydown',e=>{
      if(e.code==='Space'&&!e.repeat&&!e.target?.closest?.('input,textarea,select,[contenteditable="true"]'))requestAttackJump();
    },true);
    // Mobile: ataque na tela -> botao PULAR (sem bloquear o salto nativo).
    window.addEventListener('pointerdown',e=>{
      if(e.target?.closest?.('#jumpBtn'))requestAttackJump();
    },true);
    window.addEventListener('touchstart',e=>{
      if(e.target?.closest?.('#jumpBtn'))requestAttackJump();
    },{capture:true,passive:true});
    // PC: capturar no WINDOW antes do ouvinte legado do canvas (que aciona machado).
    window.addEventListener('pointerdown',e=>{
      if(!isSword()||!loaded||!e.target||e.target.id!=='c'||e.pointerType!=='mouse'||(e.button!==0&&e.button!==2))return;
      if(document.pointerLockElement!==e.target)return; // primeiro clique deve travar o mouse
      e.preventDefault();e.stopImmediatePropagation();
      request(e.button===2?'alt':'normal');
    },true);
    window.addEventListener('contextmenu',e=>{if(isSword()&&e.target?.id==='c')e.preventDefault();},true);
    if(mobile())setupMobile();else setupDesktopHud();
    // Respeitar cadeia de avatar/combat/câmera já instalada; não sobrescreve jogo base.
    const oldUpdate=window.__updateAnimatedAvatar;
    window.__updateAnimatedAvatar=function(...args){oldUpdate?.(...args);
      const now=performance.now(),dt=Math.min(.05,Math.max(0,Number(args[2])||((now-lastTime)/1000)));lastTime=now;
      update(dt);
      if((actionTick++%12)===0){
        const b=document.getElementById('mobileSwordAltV232');if(b)b.hidden=!isSword()||inventoryBlocked();
        updateHud();
      }
    };
    await loadFBXs();
    updateHud();
    window.gameSwordComboV232={version:VERSION,get ready(){return loaded},get active(){return !!active},get animation(){return active?.name||null},get step(){return active?.index??-1},get impactCount(){return impactCount},get clips(){return Object.fromEntries(Object.entries(clips).map(([k,v])=>[k,{duration:v.duration,tracks:v.tracks.length}]))},attack:()=>request('normal'),alternate:()=>request('alt'),cancel:()=>stopCombat()};
  }
  init().catch(e=>{failed=e;console.error('[ESPADA V233] Erro:',e);status('Espada V233 indisponível: '+(e?.message||e));window.gameSwordComboV232={version:VERSION,ready:false,error:String(e?.message||e)};});
})();

